import { fetchProjects, createProject } from './api.js';

function showAlert(message) {
  const alertDiv = document.getElementById('alert');
  alertDiv.textContent = message;
  alertDiv.style.display = 'block';
}
function hideAlert() {
  const alertDiv = document.getElementById('alert');
  alertDiv.style.display = 'none';
}
async function loadProjects() {
  const list = document.getElementById('project-list');
  list.innerHTML = '';
  const projects = await fetchProjects();
  for (const p of projects) {
    const li = document.createElement('li');
    li.dataset.testid = 'project-row';
    li.textContent = p.name + ' ';
    const btn = document.createElement('button');
    btn.textContent = 'Open project';
    btn.addEventListener('click', () => {
      location.href = `/projects/${p.id}`;
    });
    li.appendChild(btn);
    list.appendChild(li);
  }
}
document.getElementById('create-project').addEventListener('click', async () => {
  hideAlert();
  const input = document.getElementById('project-name');
  const name = input.value.trim();
  if (!name) {
    showAlert('Project name is required');
    return;
  }
  try {
    await createProject(name);
    input.value = '';
    await loadProjects();
  } catch (e) {
    showAlert(e.message);
  }
});
loadProjects();

